package de.terrestris.shoguncore.util.dialect;

import org.hibernate.dialect.Dialect;
import org.hibernate.dialect.Oracle12cDialect;

import java.sql.Types;

/**
 * SQL {@link Dialect} extending {@link Oracle12cDialect} to register
 * column mapping for LOB datatypes used in SHOGun-Core (e.g. file content
 * in {@link de.terrestris.shoguncore.model.File})
 *
 * @author Andre Henn
 * @author terrestris GmbH & co. KG
 */
public class ShogunCoreOracleDialect extends Oracle12cDialect {

    /**
     *
     */
    public ShogunCoreOracleDialect() {
        super();
    }

    /**
     *
     */
    @Override
    protected void registerLargeObjectTypeMappings() {
        super.registerLargeObjectTypeMappings();

        registerColumnType(Types.VARBINARY, "blob");
        registerColumnType(Types.LONGVARCHAR, "clob");
        registerColumnType(Types.LONGVARBINARY, "long raw");
    }
}
package de.terrestris.shoguncore.hibernate;

import com.fasterxml.jackson.core.JsonProcessingException;
import de.terrestris.shoguncore.util.json.ShogunCoreJsonObjectMapper;
import org.hibernate.HibernateException;
import org.hibernate.engine.spi.SharedSessionContractImplementor;
import org.hibernate.usertype.UserType;

import java.io.IOException;
import java.io.Serializable;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Types;
import java.util.HashMap;


/**
 * Generic jsonb user type. Annotate your entities with Map&lt;String, Object&gt; as the type.
 */
public class JsonbUserType implements UserType {

    @Override
    public Object assemble(Serializable cached, Object owner) throws HibernateException {
        return deepCopy(cached);
    }

    @Override
    public Object deepCopy(Object value) throws HibernateException {
        if (value == null) {
            return null;
        }
        ShogunCoreJsonObjectMapper mapper = new ShogunCoreJsonObjectMapper();
        if (value instanceof String) {
            try {
                return mapper.readValue(value.toString(), HashMap.class);
            } catch (IOException e) {
                throw new HibernateException(e);
            }
        }
        try {
            return mapper.readValue(mapper.writeValueAsString(value), HashMap.class);
        } catch (IOException e) {
            throw new HibernateException(e);
        }
    }

    @Override
    public Serializable disassemble(Object value) throws HibernateException {
        return (Serializable) this.deepCopy(value);
    }

    @Override
    public boolean isMutable() {
        return true;
    }

    @Override
    public Object replace(Object original, Object target, Object owner) throws HibernateException {
        return deepCopy(original);
    }

    @Override
    public Class returnedClass() {
        return HashMap.class;
    }

    @Override
    public boolean equals(Object x, Object y) throws HibernateException {
        if (x != null && y != null) {
            return x.equals(y);
        }
        return false;
    }

    @Override
    public int hashCode(Object x) throws HibernateException {
        if (x != null) {
            return x.hashCode();
        }
        return 0;
    }

    @Override
    public Object nullSafeGet(ResultSet rs, String[] names, SharedSessionContractImplementor session, Object owner) throws HibernateException, SQLException {
        if (!rs.wasNull()) {
            ShogunCoreJsonObjectMapper mapper = new ShogunCoreJsonObjectMapper();
            try {
                String string = rs.getString(names[0]);
                if (string == null) {
                    return null;
                }
                HashMap map = mapper.readValue(string, HashMap.class);
                return map;
            } catch (IOException e) {
                throw new HibernateException(e);
            }
        }
        return null;
    }

    @Override
    public void nullSafeSet(PreparedStatement st, Object value, int index, SharedSessionContractImplementor session) throws HibernateException, SQLException {
        if (value == null) {
            st.setNull(index, Types.OTHER);
        } else {
            ShogunCoreJsonObjectMapper mapper = new ShogunCoreJsonObjectMapper();
            try {
                String string = mapper.writeValueAsString(value);
                st.setObject(index, string, Types.OTHER);
            } catch (JsonProcessingException e) {
                throw new HibernateException(e);
            }
        }
    }

    @Override
    public int[] sqlTypes() {
        return new int[]{Types.OTHER};
    }

}
package de.terrestris.shoguncore.hibernate;

import org.hibernate.spatial.dialect.postgis.PostgisPG9Dialect;

import java.sql.Types;

public class ShogunPostgresqlDialect extends PostgisPG9Dialect {

    private static final long serialVersionUID = 9177170273858773475L;

    public ShogunPostgresqlDialect() {
        this.registerColumnType(Types.OTHER, "jsonb");
    }

}
package de.terrestris.shoguncore.hibernate;

import de.terrestris.shoguncore.util.json.ShogunCoreJsonObjectMapper;
import org.apache.logging.log4j.Logger;

import javax.persistence.AttributeConverter;
import javax.persistence.Converter;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

import static org.apache.logging.log4j.LogManager.getLogger;

/**
 * A JPA converter that can be used to convert jsonb fields into a map. Currently only works with 'simple' json
 * content (only one level objects like {"name": "peter", "someprop": 345}).
 * <p>
 * Please note that you'll need to switch to pgjdbc-ng from https://github.com/impossibl/pgjdbc-ng instead of using the
 * standard postgres driver.
 * <p>
 * Please also note that if you want optimal performance you'll need to add an index manually, hibernate can only create
 * btree indexes.
 */
@Converter(autoApply = true)
public class SimpleJsonbConverter implements AttributeConverter<Map<String, String>, String> {

    private static final Logger LOG = getLogger(SimpleJsonbConverter.class);

    @Override
    public String convertToDatabaseColumn(Map<String, String> attribute) {
        ShogunCoreJsonObjectMapper mapper = new ShogunCoreJsonObjectMapper();
        try {
            return (mapper.writeValueAsString(attribute));
        } catch (Exception e) {
            LOG.warn("Could not convert JSON value to PostgreSQL format: " + e.getMessage());
            LOG.debug("Stack trace: " + e.toString());
        }
        return "{}";
    }

    @Override
    public Map<String, String> convertToEntityAttribute(String dbData) {
        ShogunCoreJsonObjectMapper parser = new ShogunCoreJsonObjectMapper();
        try {
            return parser.readValue(dbData, HashMap.class);
        } catch (IOException e) {
            LOG.warn("Could not convert JSON value from PostgreSQL format: " + e.getMessage());
            LOG.debug("Stack trace: " + e.toString());
        }
        return new HashMap<>();
    }

}
