package de.terrestris.shoguncore.dao;

import jakarta.persistence.criteria.CriteriaBuilder;
import jakarta.persistence.criteria.CriteriaQuery;
import jakarta.persistence.criteria.Predicate;
import jakarta.persistence.criteria.Root;

/**
 * One restriction of a DAO query, built with the JPA Criteria API.
 * <p>
 * This replaces the legacy Hibernate <code>Criterion</code> API that has been
 * removed with Hibernate 6. Multiple restrictions that are passed to a DAO
 * method are combined with AND. Implementations may return <code>null</code>
 * to express "no restriction".
 *
 * @param <E> The type of the (root) entity that is queried
 */
@FunctionalInterface
public interface QueryRestriction<E> {

    /**
     * Creates the {@link Predicate} of this restriction.
     *
     * @param root  The root of the query
     * @param query The query the predicate will be applied to
     * @param cb    The {@link CriteriaBuilder} to build the predicate with
     * @return The predicate (or <code>null</code> for no restriction)
     */
    Predicate toPredicate(Root<E> root, CriteriaQuery<?> query, CriteriaBuilder cb);

}
