body=r'''    /**
     * Returns a list of entity objects that have field named
     * <code>fieldName</code>, which has an object <code>fieldEntity</code>
     * as value.
     *
     * @param fieldName    The name of the field
     * @param fieldEntity  The element that should be set as value
     * @param restrictions Additional restrictions to apply (optional)
     * @return The list of objects
     */
    @SafeVarargsLike
    public List<E> findAllWhereFieldEquals(String fieldName, Object fieldEntity,
                                           QueryRestriction<E>... restrictions) {

        Class<?> fieldEntityType = null;

        if (fieldEntity != null) {
            fieldEntityType = fieldEntity.getClass();
        }

        final boolean isField = EntityUtil.isField(entityClass, fieldName, fieldEntityType, true);

        if (!isField) {
            String errorMsg = String.format(
                "There is no field '%s' in the type '%s' that accepts instances of '%s'",
                fieldName,
                entityClass.getName(),
                fieldEntityType.getName()
            );
            throw new IllegalArgumentException(errorMsg);
        }

        final QueryRestriction<E> fieldRestriction = (root, query, cb) -> {
            Path<Object> fieldPath = getPath(root, fieldName);
            if (fieldEntity == null) {
                return cb.isNull(fieldPath);
            }
            return cb.equal(fieldPath, fieldEntity);
        };

        return findDistinctRootEntities(null, null, null, fieldRestriction, restrictions);
    }

    /**
     * Returns a list of entity objects that have a collection named
     * <code>fieldName</code>, which contains the passed
     * <code>subElement</code>.
     * <p>
     * The can e.g. be used to return all applications that contain a certain layer.
     *
     * @param fieldName    The name of the collection field
     * @param subElement   The element that should be contained in the collection
     * @param restrictions Additional restrictions to apply (optional)
     * @return The list of objects
     */
    @SafeVarargsLike
    public List<E> findAllWithCollectionContaining(String fieldName, PersistentObject subElement,
                                                   QueryRestriction<E>... restrictions) {
        final Class<? extends PersistentObject> subElementType = subElement.getClass();

        final boolean isCollectionField = EntityUtil.isCollectionField(entityClass, fieldName, subElementType, true);

        if (!isCollectionField) {
            String errorMsg = String.format(
                "There is no collection field '%s' with element type '%s' in the type '%s'",
                fieldName,
                subElementType.getName(),
                entityClass.getName()
            );
            throw new IllegalArgumentException(errorMsg);
        }

        final Integer subElementId = subElement.getId();

        final QueryRestriction<E> containsRestriction = (root, query, cb) -> {
            Join<E, ?> sub = root.join(fieldName);
            return cb.equal(sub.get("id"), subElementId);
        };

        return findDistinctRootEntities(null, null, null, containsRestriction, restrictions);
    }

    /**
     * Return a proxy of the object (without hitting the database). This should
     * only be used if it is assumed that the object really exists and where
     * non-existence would be an actual error.
     *
     * @param id
     * @return
     * @see http://www.mkyong.com/hibernate/different-between-session-get-and-session-load/
     */
    public E loadById(ID id) {
        logger.trace("Loading " + entityClass.getSimpleName() + " with ID " + id);
        return getSession().getReference(entityClass, id);
    }

    /**
     * Returns all Entities by calling findByCriteria(), i.e. without arguments.
     *
     * @return All entities
     * @see GenericHibernateDao#findByCriteria(QueryRestriction...)
     */
    public List<E> findAll() throws HibernateException {
        logger.trace("Finding all instances of " + entityClass.getSimpleName());
        return findByCriteria();
    }

    /**
     * Saves or updates the passed entity.
     *
     * @param e The entity to save or update in the database.
     */
    @SuppressWarnings("deprecation")
    public void saveOrUpdate(E e) {
        final Integer id = e.getId();
        final boolean hasId = id != null;
        String createOrUpdatePrefix = hasId ? "Updating" : "Creating a new";
        String idSuffix = hasId ? " with ID " + id : "";

        logger.trace(createOrUpdatePrefix + " instance of " + entityClass.getSimpleName()
            + idSuffix);

        e.setModified(DateTime.now());
        getSession().saveOrUpdate(e);
    }

    /**
     * Deletes the passed entity.
     *
     * @param e The entity to remove from the database.
     */
    @SuppressWarnings("deprecation")
    public void delete(E e) {
        logger.trace("Deleting " + entityClass.getSimpleName() + " with ID " + e.getId());
        getSession().delete(e);
    }

    /**
     * Unproxy the entity (and eagerly fetch properties).
     */
    @SuppressWarnings("unchecked")
    public E unproxy(E e) {
        if (e == null) {
            throw new NullPointerException("Entity passed for initialization is null");
        }

        Hibernate.initialize(e);

        if (e instanceof HibernateProxy) {
            e = (E) ((HibernateProxy) e).getHibernateLazyInitializer().getImplementation();
        }

        return e;
    }

    /**
     * Detach an entity from the hibernate session
     *
     * @param e
     */
    public void evict(E e) {
        logger.trace("Detaching " + entityClass.getSimpleName() + " with ID " + e.getId() + " from hibernate session");
        getSession().evict(e);
    }

    /**
     * Gets the results, that match a variable number of passed restrictions. Call
     * this method without arguments to find all entities.
     *
     * @param restrictions A variable number of restrictions (combined with AND)
     * @return Entities matching the passed restrictions
     */
    @SafeVarargsLike
    public List<E> findByCriteria(QueryRestriction<E>... restrictions) throws HibernateException {
        logger.trace("Finding instances of " + entityClass.getSimpleName()
            + " based on " + countRestrictions(restrictions) + " criteria");

        return findDistinctRootEntities(null, null, null, null, restrictions);
    }

    /**
     * Gets the results, that match a variable number of passed restrictions, but return a
     * stripped version of the entities, where only the fieldNames in <code>restrictFieldNames</code>
     * have their actual values set.
     * <p>
     * You can call this with <code>restrictFieldNames</code> = <code>null</code> to get the full
     * entities back.
     * <p>
     * You can call this method without restriction arguments to find all entities (stripped down to
     * the <code>restrictFieldNames</code>).
     * <p>
     * If this is called as <code>findByCriteriaRestricted(null)</code> the return value equals the
     * return value of <code>findByCriteria()</code>.
     *
     * @param restrictFieldNames
     * @param restrictions
     * @return
     * @throws HibernateException
     */
    @SafeVarargsLike
    public List<E> findByCriteriaRestricted(List<String> restrictFieldNames, QueryRestriction<E>... restrictions)
        throws HibernateException {
        logger.trace("Finding instances of " + entityClass.getSimpleName()
            + " based on " + countRestrictions(restrictions) + " criteria");

        if (restrictFieldNames == null) {
            return findDistinctRootEntities(null, null, null, null, restrictions);
        }

        final CriteriaBuilder cb = getSession().getCriteriaBuilder();
        final CriteriaQuery<Tuple> query = cb.createTupleQuery();
        final Root<E> root = query.from(entityClass);

        final List<Selection<?>> selections = new ArrayList<>();
        for (String restrictFieldName : restrictFieldNames) {
            selections.add(getPath(root, restrictFieldName).alias(restrictFieldName));
        }
        if (selections.isEmpty()) {
            // no field should be set at all, we only need the number of rows
            selections.add(root.get("id"));
        }
        query.multiselect(selections);

        applyRestrictions(root, query, cb, null, restrictions);

        final List<Tuple> rows = createQuery(query).getResultList();
        final List<E> result = new ArrayList<>(rows.size());

        for (Tuple row : rows) {
            final E entity = BeanUtils.instantiateClass(entityClass);
            for (int i = 0; i < restrictFieldNames.size(); i++) {
                setProperty(entity, restrictFieldNames.get(i), row.get(i));
            }
            result.add(entity);
        }

        return result;
    }

    /**
     * Gets the unique result, that matches a variable number of passed
     * restrictions.
     *
     * @param restrictions A variable number of restrictions (combined with AND)
     * @return Entity matching the passed restrictions or <code>null</code> if
     * there is no matching entity
     * @throws HibernateException if there is more than one matching result
     */
    @SafeVarargsLike
    public E findByUniqueCriteria(QueryRestriction<E>... restrictions) throws HibernateException {
        logger.trace("Finding one unique " + entityClass.getSimpleName()
            + " based on " + countRestrictions(restrictions) + " criteria");

        final List<E> results = findDistinctRootEntities(null, null, null, null, restrictions);

        if (results.isEmpty()) {
            return null;
        }
        if (results.size() > 1) {
            throw new NonUniqueResultException(results.size());
        }
        return results.get(0);
    }

    /**
     * Gets the results, that match a variable number of passed restrictions,
     * considering the paging- and sort-info at the same time.
     *
     * @param firstResult  Starting index for the paging request.
     * @param maxResults   Max number of result size.
     * @param sorters      The sort orders to apply (optional)
     * @param restrictions A variable number of restrictions (combined with AND)
     * @return
     */
    @SafeVarargsLike
    public PagingResult<E> findByCriteriaWithSortingAndPaging(Integer firstResult,
                                                              Integer maxResults, List<SortOrder> sorters,
                                                              QueryRestriction<E>... restrictions)
        throws HibernateException {

        int nrOfSorters = sorters == null ? 0 : sorters.size();

        logger.trace("Finding instances of " + entityClass.getSimpleName()
            + " based on " + countRestrictions(restrictions) + " criteria"
            + " with " + nrOfSorters + " sorters");

        if (maxResults != null) {
            logger.trace("Limiting result set size to " + maxResults);
        }
        if (firstResult != null) {
            logger.trace("Setting the first result to be retrieved to "
                + firstResult);
        }

        final List<E> results = findDistinctRootEntities(firstResult, maxResults, sorters, null, restrictions);

        return new PagingResult<E>(results, getTotalCount(restrictions));
    }

    /**
     * This method returns a {@link Map} that maps {@link PersistentObject}s
     * to PermissionCollections for the passed {@link User}. I.e. the keySet
     * of the map is the collection of all {@link PersistentObject}s where the
     * user has at least one permission and the corresponding value contains
     * the {@link PermissionCollection} for the passed user on the entity.
     *
     * @param user
     * @return
     */
    public Map<PersistentObject, PermissionCollection> findAllUserPermissionsOfUser(User user) {

        // by only joining the permissions, we will only get those entities where
        // there is at least one permission set...
        // it is hard (or even impossible in this scenario) to create a
        // restriction that filters for permissions of the given user only.
        List<PersistentObject> entitiesWithPermissions = findAllPersistentObjectsWithPermissions("userPermissions");

        Map<PersistentObject, PermissionCollection> userPermissions = new HashMap<PersistentObject, PermissionCollection>();

        // TODO find a better way than iterating over all entities of the system
        // that have at least one permission (for any user) (see comment above)
        for (PersistentObject entity : entitiesWithPermissions) {
            Map<User, PermissionCollection> entityUserPermissions = entity.getUserPermissions();
            if (entityUserPermissions.containsKey(user)) {
                userPermissions.put(entity, entityUserPermissions.get(user));
            }
        }

        return userPermissions;
    }

    /**
     * This method returns a {@link Map} that maps {@link PersistentObject}s
     * to PermissionCollections for the passed {@link UserGroup}. I.e. the keySet
     * of the map is the collection of all {@link PersistentObject}s where the
     * user group has at least one permission and the corresponding value contains
     * the {@link PermissionCollection} for the passed user group on the entity.
     *
     * @param userGroup
     * @return
     */
    public Map<PersistentObject, PermissionCollection> findAllUserGroupPermissionsOfUserGroup(UserGroup userGroup) {

        // by only joining the permissions, we will only get those entities where
        // there is at least one permission set...
        // it is hard (or even impossible in this scenario) to create a
        // restriction that filters for permissions of the given user group only.
        List<PersistentObject> entitiesWithPermissions = findAllPersistentObjectsWithPermissions("groupPermissions");

        Map<PersistentObject, PermissionCollection> userGroupPermissions = new HashMap<PersistentObject, PermissionCollection>();

        // TODO find a better way than iterating over all entities of the system
        // that have at least one permission (for any user) (see comment above)
        for (PersistentObject entity : entitiesWithPermissions) {
            Map<UserGroup, PermissionCollection> entityUserGroupPermissions = entity.getGroupPermissions();
            if (entityUserGroupPermissions.containsKey(userGroup)) {
                userGroupPermissions.put(entity, entityUserGroupPermissions.get(userGroup));
            }
        }

        return userGroupPermissions;
    }

    /**
     * Returns the total count of (distinct) db entries for the current type
     * that match the passed restrictions.
     *
     * @param restrictions A variable number of restrictions (combined with AND)
     * @return
     */
    @SafeVarargsLike
    public Number getTotalCount(QueryRestriction<E>... restrictions) throws HibernateException {
        final CriteriaBuilder cb = getSession().getCriteriaBuilder();
        final CriteriaQuery<Long> query = cb.createQuery(Long.class);
        final Root<E> root = query.from(entityClass);
        query.select(cb.countDistinct(root));
        applyRestrictions(root, query, cb, null, restrictions);
        return createQuery(query).getSingleResult();
    }

    /**
     * Helper method: Queries the distinct root entities of the {@link #entityClass}
     * of this dao that match all passed restrictions.
     *
     * @param firstResult           The first result to retrieve (optional)
     * @param maxResults            The max number of results (optional)
     * @param sorters               The sort orders to apply (optional)
     * @param additionalRestriction An additional restriction (optional)
     * @param restrictions          The restrictions (optional)
     * @return The list of distinct root entities in the order of the query results
     */
    private List<E> findDistinctRootEntities(Integer firstResult, Integer maxResults, List<SortOrder> sorters,
                                             QueryRestriction<E> additionalRestriction,
                                             QueryRestriction<E>[] restrictions) {
        final CriteriaBuilder cb = getSession().getCriteriaBuilder();
        final CriteriaQuery<E> query = cb.createQuery(entityClass);
        final Root<E> root = query.from(entityClass);
        query.select(root);

        applyRestrictions(root, query, cb, additionalRestriction, restrictions);

        if (sorters != null && !sorters.isEmpty()) {
            final List<Order> orders = new ArrayList<>(sorters.size());
            for (SortOrder sorter : sorters) {
                if (sorter == null) {
                    continue;
                }
                final Path<Object> sortPath = getPath(root, sorter.getProperty());
                orders.add(sorter.isAscending() ? cb.asc(sortPath) : cb.desc(sortPath));
            }
            query.orderBy(orders);
        }

        final TypedQuery<E> typedQuery = createQuery(query);

        if (maxResults != null) {
            typedQuery.setMaxResults(maxResults);
        }
        if (firstResult != null) {
            typedQuery.setFirstResult(firstResult);
        }

        return distinct(typedQuery.getResultList());
    }

    /**
     * Helper method: Returns all (distinct) persistent objects of all entity types
     * that have at least one entry in the passed permission map property.
     *
     * @param permissionsProperty Either <code>userPermissions</code> or <code>groupPermissions</code>
     * @return The list of persistent objects with permissions
     */
    private List<PersistentObject> findAllPersistentObjectsWithPermissions(String permissionsProperty) {
        final Session session = getSession();
        final CriteriaBuilder cb = session.getCriteriaBuilder();
        final List<PersistentObject> result = new ArrayList<>();

        for (EntityType<?> entityType : session.getMetamodel().getEntities()) {
            final Class<?> javaType = entityType.getJavaType();
            if (javaType == null || !PersistentObject.class.isAssignableFrom(javaType)
                || hasEntitySuperType(entityType)) {
                // only query the root entities of each hierarchy, subtypes will be
                // contained in the results of the (polymorphic) root queries
                continue;
            }
            @SuppressWarnings("unchecked")
            final Class<PersistentObject> persistentObjectType = (Class<PersistentObject>) javaType;
            final CriteriaQuery<PersistentObject> query = cb.createQuery(persistentObjectType);
            final Root<PersistentObject> root = query.from(persistentObjectType);
            root.join(permissionsProperty);
            query.select(root);
            result.addAll(createQuery(query).getResultList());
        }

        return distinct(result);
    }

    /**
     * @param entityType
     * @return Whether the passed entity type has a supertype that is an entity itself
     */
    private static boolean hasEntitySuperType(EntityType<?> entityType) {
        IdentifiableType<?> superType = entityType.getSupertype();
        while (superType != null) {
            if (superType instanceof EntityType) {
                return true;
            }
            superType = superType.getSupertype();
        }
        return false;
    }

    /**
     * Helper method: Creates the (typed) query and sets the cacheable hint.
     *
     * @param criteriaQuery
     * @param <T>
     * @return
     */
    private <T> TypedQuery<T> createQuery(CriteriaQuery<T> criteriaQuery) {
        final org.hibernate.query.Query<T> query = getSession().createQuery(criteriaQuery);
        query.setCacheable(Boolean.TRUE.equals(this.useQueryCache));
        return query;
    }

    /**
     * Helper method: Adds all (non null) restrictions to the query (combined with AND).
     *
     * @param root
     * @param query
     * @param cb
     * @param additionalRestriction An additional restriction (may be null)
     * @param restrictions          The restrictions (may be null or contain null values)
     */
    private void applyRestrictions(Root<E> root, CriteriaQuery<?> query, CriteriaBuilder cb,
                                   QueryRestriction<E> additionalRestriction,
                                   QueryRestriction<E>[] restrictions) {
        final List<Predicate> predicates = new ArrayList<>();

        if (additionalRestriction != null) {
            addPredicate(predicates, additionalRestriction.toPredicate(root, query, cb));
        }
        if (restrictions != null) {
            for (QueryRestriction<E> restriction : restrictions) {
                if (restriction != null) {
                    addPredicate(predicates, restriction.toPredicate(root, query, cb));
                }
            }
        }

        if (!predicates.isEmpty()) {
            query.where(predicates.toArray(new Predicate[0]));
        }
    }

    /**
     * @param predicates
     * @param predicate
     */
    private static void addPredicate(List<Predicate> predicates, Predicate predicate) {
        if (predicate != null) {
            predicates.add(predicate);
        }
    }

    /**
     * @param restrictions
     * @return The number of passed restrictions
     */
    private static int countRestrictions(QueryRestriction<?>[] restrictions) {
        return restrictions == null ? 0 : restrictions.length;
    }

    /**
     * Resolves a (possibly dotted) property path, e.g. <code>name</code> or
     * <code>owner.name</code>.
     *
     * @param root
     * @param property
     * @return
     */
    private static Path<Object> getPath(Root<?> root, String property) {
        Path<Object> path = null;
        for (String part : property.split("\\.")) {
            path = path == null ? root.get(part) : path.get(part);
        }
        return path;
    }

    /**
     * Returns a list containing the distinct elements of the passed collection
     * (in the original order).
     *
     * @param results
     * @param <T>
     * @return
     */
    private static <T> List<T> distinct(Collection<T> results) {
        return new ArrayList<>(new LinkedHashSet<>(results));
    }

    /**
     * Sets the value of the property on the passed bean. Uses the setter if
     * available, otherwise the value is set on the field directly.
     *
     * @param bean
     * @param propertyName
     * @param value
     */
    private static void setProperty(Object bean, String propertyName, Object value) {
        final BeanWrapper beanWrapper = PropertyAccessorFactory.forBeanPropertyAccess(bean);
        if (beanWrapper.isWritableProperty(propertyName)) {
            beanWrapper.setPropertyValue(propertyName, value);
        } else {
            new DirectFieldAccessor(bean).setPropertyValue(propertyName, value);
        }
    }

