package de.terrestris.shoguncore.hibernate;

import jakarta.persistence.AttributeConverter;
import jakarta.persistence.Converter;
import org.joda.time.LocalDate;

/**
 * A JPA converter that persists Joda {@link LocalDate} values as SQL dates.
 * <p>
 * This replaces the <code>org.jadira.usertype.dateandtime.joda.PersistentLocalDate</code>
 * user type, which is not available for Hibernate 6.
 */
@Converter
public class JodaLocalDateConverter implements AttributeConverter<LocalDate, java.sql.Date> {

    @Override
    public java.sql.Date convertToDatabaseColumn(LocalDate attribute) {
        if (attribute == null) {
            return null;
        }
        return java.sql.Date.valueOf(java.time.LocalDate.of(
            attribute.getYear(), attribute.getMonthOfYear(), attribute.getDayOfMonth()));
    }

    @Override
    public LocalDate convertToEntityAttribute(java.sql.Date dbData) {
        if (dbData == null) {
            return null;
        }
        java.time.LocalDate localDate = dbData.toLocalDate();
        return new LocalDate(localDate.getYear(), localDate.getMonthValue(), localDate.getDayOfMonth());
    }

}
