package de.terrestris.shoguncore.util.dialect;

import org.hibernate.dialect.Dialect;
import org.hibernate.dialect.OracleDialect;

import java.sql.Types;

/**
 * SQL {@link Dialect} extending {@link OracleDialect} to register
 * column mapping for LOB datatypes used in SHOGun-Core (e.g. file content
 * in {@link de.terrestris.shoguncore.model.File})
 *
 * @author Andre Henn
 * @author terrestris GmbH & co. KG
 */
public class ShogunCoreOracleDialect extends OracleDialect {

    /**
     *
     */
    public ShogunCoreOracleDialect() {
        super();
    }

    /**
     * Registers the column mappings for the large object types.
     */
    @Override
    protected String columnType(int sqlTypeCode) {
        switch (sqlTypeCode) {
            case Types.VARBINARY:
                return "blob";
            case Types.LONGVARCHAR:
                return "clob";
            case Types.LONGVARBINARY:
                return "long raw";
            default:
                return super.columnType(sqlTypeCode);
        }
    }
}
EOF
