package de.terrestris.shoguncore.hibernate;

import org.hibernate.dialect.PostgreSQLDialect;

import java.sql.Types;

/**
 * PostgreSQL dialect that maps {@link Types#OTHER} (e.g. used by the
 * {@link JsonbUserType}) to <code>jsonb</code> columns.
 * <p>
 * The spatial (PostGIS) functions and types are contributed to the
 * {@link PostgreSQLDialect} automatically by hibernate-spatial.
 */
public class ShogunPostgresqlDialect extends PostgreSQLDialect {

    public ShogunPostgresqlDialect() {
        super();
    }

    @Override
    protected String columnType(int sqlTypeCode) {
        if (sqlTypeCode == Types.OTHER) {
            return "jsonb";
        }
        return super.columnType(sqlTypeCode);
    }

}
