import re
def parse(p):
    cls=None; res={}
    for line in open(p):
        line=line.rstrip()
        m=re.match(r'^(?:public |protected )?.*?(?:class|interface|enum) ([\w.$]+)',line)
        if line.startswith('Compiled from'): continue
        if m and line.endswith('{'):
            cls=m.group(1); res.setdefault(cls,set()); res[cls].add('HEADER '+line); continue
        if line.strip() in ('}',''): continue
        res[cls].add(line.strip())
    return res
def norm(x):
    x=re.sub(r'\bjavax\.(persistence|servlet|transaction|mail|annotation)\b',r'jakarta.\1',x)
    return x
old=parse('old.txt'); new=parse('new.txt')
for c in sorted(old):
    o={norm(x) for x in old[c]}; n=new.get(c,set())
    missing=o-n
    if missing:
        print('==',c)
        for m in sorted(missing): print('  -',m)
        extra=n-o
        for m in sorted(extra): print('  +',m)
EOF

