package de.terrestris.shoguncore.util.dialect;

import org.hibernate.dialect.Dialect;
import org.hibernate.dialect.OracleDialect;

import java.sql.Types;
import java.util.HashMap;
import java.util.Map;

/**
 * SQL {@link Dialect} extending {@link OracleDialect} to register
 * column mapping for LOB datatypes used in SHOGun-Core (e.g. file content
 * in {@link de.terrestris.shoguncore.model.File})
 * <p>
 * Hibernate 6 removed the <code>Oracle12cDialect</code> (the {@link OracleDialect}
 * covers all versions) and the <code>registerColumnType</code> API of the dialects.
 * The column types registered in {@link #registerLargeObjectTypeMappings()} are
 * therefore applied in {@link #columnType(int)}.
 *
 * @author Andre Henn
 * @author terrestris GmbH & co. KG
 */
public class ShogunCoreOracleDialect extends OracleDialect {

    /**
     * The column types (by JDBC type code) that override the ones of the {@link OracleDialect}.
     */
    private Map<Integer, String> columnTypes;

    /**
     *
     */
    public ShogunCoreOracleDialect() {
        super();
    }

    /**
     * Registers the column mappings for the large object types. Subclasses
     * may override this method (calling super) to register further types via
     * {@link #registerColumnType(int, String)}.
     */
    protected void registerLargeObjectTypeMappings() {
        registerColumnType(Types.VARBINARY, "blob");
        registerColumnType(Types.LONGVARCHAR, "clob");
        registerColumnType(Types.LONGVARBINARY, "long raw");
    }

    /**
     * Registers the column type to use for the given JDBC type code.
     *
     * @param sqlTypeCode The JDBC type code (see {@link Types})
     * @param columnType  The column type
     */
    protected void registerColumnType(int sqlTypeCode, String columnType) {
        columnTypes.put(sqlTypeCode, columnType);
    }

    /**
     * Returns the registered column type for the JDBC type code (if any) or
     * the one of the {@link OracleDialect}.
     */
    @Override
    protected String columnType(int sqlTypeCode) {
        if (columnTypes == null) {
            columnTypes = new HashMap<>();
            registerLargeObjectTypeMappings();
        }
        String columnType = columnTypes.get(sqlTypeCode);
        return columnType != null ? columnType : super.columnType(sqlTypeCode);
    }
}
EOF
