package de.terrestris.shoguncore.util.dialect;

import org.hibernate.dialect.OracleDialect;
import org.junit.jupiter.api.Test;

import java.sql.Types;

import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * Tests the column types of the {@link ShogunCoreOracleDialect}.
 */
public class ShogunCoreOracleDialectTest {

    @Test
    public void registersLargeObjectTypeMappings() {
        ShogunCoreOracleDialect dialect = new ShogunCoreOracleDialect();

        assertEquals("blob", dialect.columnType(Types.VARBINARY));
        assertEquals("clob", dialect.columnType(Types.LONGVARCHAR));
        assertEquals("long raw", dialect.columnType(Types.LONGVARBINARY));
    }

    @Test
    public void usesTheColumnTypesOfTheOracleDialectOtherwise() {
        ShogunCoreOracleDialect dialect = new ShogunCoreOracleDialect();
        OracleDialect oracleDialect = new OracleDialect() {
            String publicColumnType(int sqlTypeCode) {
                return columnType(sqlTypeCode);
            }

            @Override
            protected String columnType(int sqlTypeCode) {
                return super.columnType(sqlTypeCode);
            }
        };

        assertEquals(new OracleDialectColumnTypes(oracleDialect).get(Types.VARCHAR), dialect.columnType(Types.VARCHAR));
        assertEquals(new OracleDialectColumnTypes(oracleDialect).get(Types.INTEGER), dialect.columnType(Types.INTEGER));
    }

    @Test
    public void subclassesCanRegisterFurtherColumnTypes() {
        ShogunCoreOracleDialect dialect = new ShogunCoreOracleDialect() {
            @Override
            protected void registerLargeObjectTypeMappings() {
                super.registerLargeObjectTypeMappings();
                registerColumnType(Types.CLOB, "nclob");
            }
        };

        assertEquals("nclob", dialect.columnType(Types.CLOB));
        assertEquals("blob", dialect.columnType(Types.VARBINARY));
    }

    /**
     * Helper to access the (protected) column types of a plain {@link OracleDialect}.
     */
    private static final class OracleDialectColumnTypes extends OracleDialect {
        private final OracleDialect dialect;

        OracleDialectColumnTypes(OracleDialect dialect) {
            this.dialect = dialect;
        }

        String get(int sqlTypeCode) {
            return super.columnType(sqlTypeCode);
        }
    }
}
