package org.hibernate.dialect;

import org.hibernate.engine.jdbc.dialect.spi.DialectResolutionInfo;

/**
 * Compatibility class for the <code>Oracle12cDialect</code> that was removed with
 * Hibernate 6.3 (the {@link OracleDialect} supports all Oracle versions and
 * determines the version of the database itself).
 * <p>
 * It is provided by SHOGun-Core, as the
 * {@link de.terrestris.shoguncore.util.dialect.ShogunCoreOracleDialect} extends it
 * (and existing configurations may refer to it).
 *
 * @deprecated use {@link OracleDialect} instead
 */
@Deprecated
public class Oracle12cDialect extends OracleDialect {

    public Oracle12cDialect() {
        super();
    }

    public Oracle12cDialect(DialectResolutionInfo info) {
        super(info);
    }
}
EOF
