package org.hibernate.spatial.dialect.postgis;

import org.hibernate.dialect.PostgreSQLDialect;
import org.hibernate.engine.jdbc.dialect.spi.DialectResolutionInfo;

/**
 * Compatibility class for the <code>PostgisPG9Dialect</code> of Hibernate Spatial 5,
 * which is not available with Hibernate 6. Since Hibernate 6, the spatial (PostGIS)
 * functions and types are contributed to the {@link PostgreSQLDialect} automatically,
 * as e.g. for the {@link PostgisPG95Dialect} that is still part of Hibernate Spatial.
 * <p>
 * It is provided by SHOGun-Core, as the
 * {@link de.terrestris.shoguncore.hibernate.ShogunPostgresqlDialect} extends it
 * (and existing configurations may refer to it).
 *
 * @deprecated use {@link PostgreSQLDialect} instead
 */
@Deprecated
public class PostgisPG9Dialect extends PostgreSQLDialect {

    public PostgisPG9Dialect() {
        super();
    }

    public PostgisPG9Dialect(DialectResolutionInfo info) {
        super(info);
    }
}
EOF
