package de.terrestris.shoguncore.hibernate;

import org.hibernate.dialect.PostgreSQLDialect;
import org.junit.jupiter.api.Test;

import java.sql.Types;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests the column types of the {@link ShogunPostgresqlDialect}.
 */
public class ShogunPostgresqlDialectTest {

    @Test
    public void mapsOtherToJsonb() {
        assertEquals("jsonb", new ShogunPostgresqlDialect().columnType(Types.OTHER));
    }

    @Test
    public void isAPostgreSQLDialect() {
        ShogunPostgresqlDialect dialect = new ShogunPostgresqlDialect();

        assertTrue(dialect instanceof PostgreSQLDialect);
        assertEquals(new PlainPostgreSQLDialect().columnType(Types.VARCHAR), dialect.columnType(Types.VARCHAR));
    }

    /**
     * A plain {@link PostgreSQLDialect}, whose (protected) column types are
     * accessible in this package.
     */
    private static final class PlainPostgreSQLDialect extends PostgreSQLDialect {
        @Override
        protected String columnType(int sqlTypeCode) {
            return super.columnType(sqlTypeCode);
        }
    }
}
EOF
